#pragma once
// Select the device test data through a build flag (platformio.ini): HW_DATASET_INSTANCE, HW_DATASET_ETHZ,
// or the default, STEAD. The header is generated by 10_make_hw_eval_inputs.py.
#if defined(HW_DATASET_INSTANCE)
#include "hw_eval_instance.h"
#elif defined(HW_DATASET_ETHZ)
#include "hw_eval_ethz.h"
#else
#include "hw_eval_stead.h"
#endif

// The i-th (dequantized) sample of trace k; i counts from the start of the trace.
static inline float hwSample(int k, int i) { return HW_DATA[HW_OFFSET[k] + i] * HW_SCALE[k]; }
